    <section class="projects" aria-label="Tasks">${rows}</section>`);
}

const taskFilter = value => ['Open', 'Completed'].includes(value) ? value : 'All';
const priorityFilter = value => ['Low', 'Normal', 'High'].includes(value) ? value : 'All';
const projectLocation = (id, filter, priority) => `/projects/${id}?filter=${filter}${priority === 'All' ? '' : `&priorityFilter=${priority}`}`;

function validDueDate(value) {
  if (value === '') return true;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

async function readForm(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk.toString();
    if (Buffer.byteLength(body) > 65536) return null;
  }
  return new URLSearchParams(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function html(res, status, content) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(content);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'GET' && url.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok' }));
      return;
    }
    if (req.method === 'GET' && url.pathname === '/') {
      html(res, 200, home('', url.searchParams.get('filter') === 'Archived' ? 'Archived' : 'Active'));
      return;
    }
    if (req.method === 'POST' && url.pathname === '/projects') {
      let body = '';
      for await (const chunk of req) {
        body += chunk.toString();
        if (Buffer.byteLength(body) > 65536) {
          html(res, 413, page('Request too large', '<h1>Request too large</h1>'));
          return;
        }
      }
      const name = (new URLSearchParams(body).get('name') || '').trim();
      if (!name) {
        html(res, 200, home('Project name is required'));
        return;
      }
      addProject.run(name);
      res.writeHead(303, { Location: '/' });
      res.end();
      return;
    }
    const archiveMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/(archive|restore)$/);
    if (req.method === 'POST' && archiveMatch) {
      const result = setArchived.run(archiveMatch[2] === 'archive' ? 1 : 0, archiveMatch[1]);
      if (result.changes) {
        redirect(res, archiveMatch[2] === 'archive' ? '/' : '/?filter=Archived');
        return;
      }
    }
    const match = url.pathname.match(/^\/projects\/([1-9]\d*)$/);
    if (req.method === 'GET' && match) {
      const project = getProject.get(match[1]);
      if (project) {
        html(res, 200, projectPage(project, taskFilter(url.searchParams.get('filter')), '', priorityFilter(url.searchParams.get('priorityFilter'))));
        return;
      }
    }
    const defaultMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/default-priority$/);
    if (req.method === 'POST' && defaultMatch) {
      const project = getProject.get(defaultMatch[1]);
      if (project) {
        const form = await readForm(req);
        if (!form) {
          html(res, 413, page('Request too large', '<h1>Request too large</h1>'));
          return;
        }
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        if (project.archived) {
          html(res, 403, projectPage(project, filter, 'Archived project is read-only', priority));
          return;
        }
        const value = form.get('priority');
        if (!['Low', 'Normal', 'High'].includes(value)) {
          html(res, 400, projectPage(project, filter, 'Invalid task priority', priority));
          return;
        }
        setDefaultPriority.run(value, project.id);
        redirect(res, projectLocation(project.id, filter, priority));
        return;
      }
    }
    const renameMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/rename$/);
    if (req.method === 'POST' && renameMatch) {
      const project = getProject.get(renameMatch[1]);
      if (project) {
        if (project.archived) {
          html(res, 403, projectPage(project, 'All', 'Archived project is read-only'));
          return;
        }
        const form = await readForm(req);
        if (!form) {
          html(res, 413, page('Request too large', '<h1>Request too large</h1>'));
          return;
        }
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        const name = (form.get('name') || '').trim();
        if (!name) {
          html(res, 200, projectPage(project, filter, 'Project name is required', priority));
          return;
        }
        renameProject.run(name, project.id);
        redirect(res, projectLocation(project.id, filter, priority));
        return;
      }
    }
    const taskMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*)(\/(?:rename|priority|due-date))?)?$/);
    if (req.method === 'POST' && taskMatch) {
      const project = getProject.get(taskMatch[1]);
      if (project) {
        if (project.archived) {
          html(res, 403, projectPage(project, 'All', 'Archived project is read-only'));
          return;
        }
        const form = await readForm(req);
        if (!form) {
          html(res, 413, page('Request too large', '<h1>Request too large</h1>'));
          return;
        }
        const filter = taskFilter(form.get('filter'));
        const selectedPriority = priorityFilter(form.get('priorityFilter'));
        if (taskMatch[3] === '/due-date') {
          if (!getTask.get(taskMatch[2], project.id)) {
            html(res, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
          const dueDate = (form.get('dueDate') || '').trim();
          if (!validDueDate(dueDate)) {
            html(res, 200, projectPage(project, filter, 'Due date must be a valid YYYY-MM-DD date', selectedPriority));
            return;
          }
          setDueDate.run(dueDate, taskMatch[2], project.id);
        } else if (taskMatch[3] === '/priority') {
          const priority = form.get('priority');
          if (!['Low', 'Normal', 'High'].includes(priority)) {
            html(res, 400, projectPage(project, filter, 'Invalid task priority', selectedPriority));
            return;
          }
          if (!setPriority.run(priority, taskMatch[2], project.id).changes) {
            html(res, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
        } else if (taskMatch[3] === '/rename') {
          if (!getTask.get(taskMatch[2], project.id)) {
            html(res, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
          const title = (form.get('title') || '').trim();
          if (!title) {
            html(res, 200, projectPage(project, filter, 'Task title is required', selectedPriority));
            return;
          }
          renameTask.run(title, taskMatch[2], project.id);
        } else if (taskMatch[2]) {
          const result = updateTask.run(form.get('completed') === '1' ? 1 : 0, taskMatch[2], project.id);
          if (!result.changes) {
            html(res, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
        } else {
          const title = (form.get('title') || '').trim();
          if (!title) {
            html(res, 200, projectPage(project, filter, 'Task title is required', selectedPriority));
            return;
          }
          addTask.run(project.id, title, project.default_priority);
        }
        redirect(res, projectLocation(project.id, filter, selectedPriority));
        return;
      }
    }
    html(res, 404, page('Not found', '<h1>Not found</h1><form action="/" method="get"><button>Projects</button></form>'));
  } catch (error) {
    console.error(error);
    if (!res.headersSent) html(res, 500, page('Error', '<h1>Something went wrong</h1>'));
    else res.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => { db.close(); process.exit(0); });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { DatabaseSync } from 'node:sqlite';

test('due dates validate Gregorian days, migrate, preserve task data and filters, and persist', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'workboard-dates-'));
  const dbPath = join(dir, 'db.sqlite');
  const legacy = new DatabaseSync(dbPath);
  legacy.exec(`CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0);
    INSERT INTO projects (name) VALUES ('Legacy');
    INSERT INTO tasks (project_id, title, completed) VALUES (1, 'Existing', 1);`);
  legacy.close();
  let child, url;
  const start = async () => {
    child = spawn(process.execPath, ['server.js'], { env: { ...process.env, PORT: '0', DB_PATH: dbPath }, stdio: ['ignore', 'pipe', 'pipe'] });
    url = await new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('Startup timeout')), 5000);
      child.once('exit', code => { clearTimeout(timer); reject(new Error(`Exited ${code}`)); });
      child.stdout.on('data', chunk => {
        const match = chunk.toString().match(/listening on port (\d+)/);
        if (match) { clearTimeout(timer); resolve(`http://127.0.0.1:${match[1]}`); }
      });
    });
  };
  const stop = async () => { const exited = once(child, 'exit'); child.kill(); await exited; child = null; };
  const post = (path, values = {}) => fetch(url + path, { method: 'POST', body: new URLSearchParams(values), redirect: 'manual' });
  const page = path => fetch(url + path).then(r => r.text());
  const dateInput = (html, id) => html.match(new RegExp(`<input id="task-due-date-${id}"[^>]*>`))[0];
  const save = value => post('/projects/1/tasks/1/due-date', { dueDate: value, filter: 'Completed', priorityFilter: 'Normal' });
  const filtered = '/projects/1?filter=Completed&priorityFilter=Normal';
  try {
    await start();
    await post('/projects', { name: 'Second' });
    await post('/projects/1/tasks', { title: 'New task' });
    await post('/projects/2/tasks', { title: 'Other project' });
    assert.match(dateInput(await page('/projects/1'), 1), /value=""/);
    assert.match(dateInput(await page('/projects/1'), 2), /value=""/);
    const before = await page(filtered);
    for (const value of ['0001-01-01', '9999-12-31', '2000-02-29', '2024-02-29', '1900-02-28', '2025-04-30']) {
      const response = await save(`  ${value}  `);
      assert.equal(response.status, 303);
      assert.equal(response.headers.get('location'), filtered);
      const after = await page(filtered);
      assert.match(dateInput(after, 1), new RegExp(`value="${value}"`));
      assert.equal(after.replace(dateInput(after, 1), ''), before.replace(dateInput(before, 1), ''));
    }
    for (const value of ['0000-01-01', '10000-01-01', '1900-02-29', '2025-02-29', '2024-02-30', '2025-04-31', '2025-00-01', '2025-13-01', '2025-01-00', '2025-01-32', '2025-1-01', '25-01-01', '2025-01-01T00:00:00Z', '<bad>']) {
      const response = await save(value);
      assert.equal(response.status, 200);
      const html = await response.text();
      assert.match(html, /role="alert">Due date must be a valid YYYY-MM-DD date/);
      assert.match(dateInput(html, 1), /value="2025-04-30"/);
      assert.match(html, /<option selected>Completed/);
      assert.match(html, /<option selected>Normal/);
    }
    assert.equal((await post('/projects/2/tasks/1/due-date', { dueDate: '2025-01-01' })).status, 404);
    assert.match(dateInput(await page('/projects/2'), 3), /value=""/);
    await post('/projects/1/tasks/2/due-date', { dueDate: '2026-12-31' });
    await post('/projects/1/tasks/1/rename', { title: 'Renamed' });
    assert.match(dateInput(await page(filtered), 1), /value="2025-04-30"/);
    assert.match(await page('/'), /1\/2 completed/);
    let detail = await page('/projects/1');
    await stop(); await start();
    assert.equal(await page('/projects/1'), detail);
    await post('/projects/1/archive');
    detail = await page('/projects/1');
    for (const id of [1, 2]) assert.match(dateInput(detail, id), / disabled/);
    assert.equal((detail.match(/<button type="submit" disabled>Save due date/g) || []).length, 2);
    assert.equal((await save('2027-01-01')).status, 403);
    assert.match(dateInput(await page(filtered), 1), /value="2025-04-30"/);
    await stop(); await start();
    assert.equal(await page('/projects/1'), detail);
    await post('/projects/1/restore');
    assert.doesNotMatch(dateInput(await page('/projects/1'), 1), / disabled/);
    await save('   ');
    assert.match(dateInput(await page(filtered), 1), /value=""/);
    assert.match(dateInput(await page('/projects/1'), 2), /value="2026-12-31"/);
    await save('2028-02-29');
    await save('');
    detail = await page('/projects/1');
    await stop(); await start();
    assert.equal(await page('/projects/1'), detail);
  } finally {
    if (child) await stop();
    await rm(dir, { recursive: true, force: true });
  }
});

